GUARDS = "CREATE OR REPLACE FUNCTION cehub_project.guard_customer_report_package() RETURNS trigger LANGUAGE plpgsql\nSET search_path=pg_catalog AS $$\nDECLARE projection jsonb;\nBEGIN\n PERFORM 1 FROM cehub_project.projects WHERE tenant_id=NEW.tenant_id AND id=NEW.project_id FOR UPDATE;\n projection=NEW.snapshot->'projection';\n IF projection->>'template_version'='customer-audit-evidence.v1' THEN\n  IF NEW.audit_report_id IS NULL OR NEW.draft->>'audit_report_id' IS DISTINCT FROM NEW.audit_report_id::text\n  OR NEW.snapshot->'draft' IS DISTINCT FROM NEW.draft OR NEW.draft->>'customer_id' IS DISTINCT FROM NEW.customer_id::text\n  OR NEW.snapshot->>'customer_id' IS DISTINCT FROM NEW.customer_id::text OR NEW.snapshot->>'digest' IS DISTINCT FROM NEW.source_digest\n  OR projection->>'title' IS DISTINCT FROM NEW.draft->>'title'\n  OR projection - ARRAY['template_version','title','customer_name','audit_clauses','documents','interpretation'] <> '{}'::jsonb\n  OR jsonb_typeof(projection->'audit_clauses') IS DISTINCT FROM 'array' OR jsonb_typeof(projection->'documents') IS DISTINCT FROM 'array'\n  OR jsonb_array_length(projection->'audit_clauses')<>jsonb_array_length(NEW.draft->'clauses')\n  OR jsonb_array_length(projection->'documents')<>jsonb_array_length(NEW.draft->'documents')\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(projection->'audit_clauses') v WHERE v - ARRAY['standard','edition','clause','requirement','statement','applicability','gap','signature_summaries'] <> '{}'::jsonb)\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(projection->'documents') v WHERE v - ARRAY['filename','path','sha256','size_bytes','media_type'] <> '{}'::jsonb)\n  OR NOT EXISTS(SELECT 1 FROM cehub_project.project_report_exports WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.audit_report_id AND kind='audit')\n  OR EXISTS(SELECT 1 FROM cehub_project.project_report_withdrawals WHERE tenant_id=NEW.tenant_id AND report_id=NEW.audit_report_id)\n  THEN RAISE EXCEPTION 'Customer audit disclosure requires fixed whitelist and actual audit report'; END IF;\n  RETURN NEW;\n END IF;\n IF NEW.audit_report_id IS NOT NULL THEN RAISE EXCEPTION 'Legacy customer report cannot carry audit scope'; END IF;\n\n IF NEW.snapshot->'draft' IS DISTINCT FROM NEW.draft\n OR NEW.draft->>'customer_id' IS DISTINCT FROM NEW.customer_id::text\n OR NEW.snapshot->>'customer_id' IS DISTINCT FROM NEW.customer_id::text\n OR NEW.snapshot->>'digest' IS DISTINCT FROM NEW.source_digest\n OR projection->>'template_version' IS DISTINCT FROM 'customer-reply-commitment.v1'\n OR projection->>'title' IS DISTINCT FROM NEW.draft->>'title'\n OR jsonb_typeof(projection) IS DISTINCT FROM 'object'\n OR projection - ARRAY['template_version','title','customer_name','approved_replies','commitments','interpretation'] <> '{}'::jsonb\n OR jsonb_typeof(projection->'approved_replies') IS DISTINCT FROM 'array'\n OR jsonb_typeof(projection->'commitments') IS DISTINCT FROM 'array'\n OR jsonb_array_length(projection->'approved_replies')<>jsonb_array_length(NEW.draft->'reply_ids')\n OR jsonb_array_length(projection->'commitments')<>jsonb_array_length(NEW.draft->'milestones')\n OR EXISTS (SELECT 1 FROM jsonb_array_elements(projection->'approved_replies') r WHERE r - ARRAY['reference','approved_reply','lead_time_days','reply_approved_at'] <> '{}'::jsonb)\n OR EXISTS (SELECT 1 FROM jsonb_array_elements(projection->'commitments') r WHERE r - ARRAY['milestone','committed_finish','confirmed_at'] <> '{}'::jsonb)\n THEN RAISE EXCEPTION 'Customer report requires explicit customer-visible whitelist and actual input scope'; END IF;\n RETURN NEW;\nEND $$;\nCREATE OR REPLACE FUNCTION cehub_project.guard_customer_report_file() RETURNS trigger LANGUAGE plpgsql\nSET search_path=pg_catalog AS $$\nDECLARE d cehub_project.customer_report_decisions;\nBEGIN\n PERFORM 1 FROM cehub_project.projects WHERE tenant_id=NEW.tenant_id AND id=NEW.project_id FOR UPDATE;\n SELECT * INTO d FROM cehub_project.customer_report_decisions WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND package_id=NEW.package_id ORDER BY version DESC LIMIT 1;\n IF d.id IS DISTINCT FROM NEW.decision_id OR d.action IS DISTINCT FROM 'approved'\n THEN RAISE EXCEPTION 'Customer report files require the current approved projection'; END IF;\n IF NEW.format='zip' AND NOT EXISTS(SELECT 1 FROM cehub_project.customer_report_packages WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.package_id AND audit_report_id IS NOT NULL) THEN RAISE EXCEPTION 'Customer ZIP requires approved audit disclosure'; END IF;\n RETURN NEW;\nEND $$;\n\nCREATE FUNCTION cehub_project.guard_customer_report_document() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE p cehub_project.customer_report_packages;\nBEGIN\n SELECT * INTO p FROM cehub_project.customer_report_packages WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.package_id;\n IF p.audit_report_id IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.draft->'documents') v WHERE v->>'document_id'=NEW.document_id::text AND v->>'source_document_id'=NEW.source_document_id::text)\n OR NOT EXISTS(SELECT 1 FROM cehub_project.project_report_sources WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND report_id=p.audit_report_id AND document_id=NEW.source_document_id)\n THEN RAISE EXCEPTION 'Disclosed file requires explicit original and actual project file'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION cehub_project.guard_customer_audit_documents() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nBEGIN\n IF NEW.audit_report_id IS NOT NULL AND (SELECT count(*) FROM cehub_project.customer_report_documents WHERE tenant_id=NEW.tenant_id AND package_id=NEW.id) IS DISTINCT FROM jsonb_array_length(NEW.draft->'documents')::bigint THEN RAISE EXCEPTION 'Customer audit document references must be complete'; END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER guard_customer_report_document BEFORE INSERT ON cehub_project.customer_report_documents FOR EACH ROW EXECUTE FUNCTION cehub_project.guard_customer_report_document();\nCREATE CONSTRAINT TRIGGER guard_customer_audit_documents AFTER INSERT ON cehub_project.customer_report_packages DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cehub_project.guard_customer_audit_documents();\nCREATE TRIGGER immutable_customer_report_document BEFORE UPDATE OR DELETE ON cehub_project.customer_report_documents FOR EACH ROW EXECUTE FUNCTION cehub_ai.protect_checkpoint_history();\nREVOKE ALL ON cehub_project.customer_report_documents FROM PUBLIC;\nREVOKE ALL ON FUNCTION cehub_project.guard_customer_report_document(), cehub_project.guard_customer_audit_documents() FROM PUBLIC;\n"

